      UPDATE TH_BUF_OUT_DELIVERY_ORDER
      SET    TH_BUF_OUT_DELIVERY_ORDER.DELIVERY_ORDER_ID += '::' + CONVERT(NVARCHAR, B.SEQ)
      FROM   TH_BUF_OUT_DELIVERY_ORDER A,
             (
              SELECT A.*,
                     COUNT(1) OVER (PARTITION BY DELIVERY_ORDER_ID ORDER BY DELIVERY_ORDER_SEQ) SEQ
              FROM   TH_BUF_OUT_DELIVERY_ORDER A
              WHERE  A.MASTER_ID = @V_MASTER_ID 
              AND    A.PLAN_ID = @V_PLAN_ID 
              AND    A.OUT_VERSION_ID = @V_OUT_VERSION_ID 
             ) B
      WHERE  A.MASTER_ID = @V_MASTER_ID 
      AND    A.PLAN_ID = @V_PLAN_ID 
      AND    A.OUT_VERSION_ID = @V_OUT_VERSION_ID 
      AND    A.DELIVERY_ORDER_ID = B.DELIVERY_ORDER_ID
      AND    A.DELIVERY_ORDER_SEQ = B.DELIVERY_ORDER_SEQ
      AND    B.SEQ > 1
      
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_BUF_OUT_DELIVERY_ORDER', 'UPDATE', @@ROWCOUNT, null, 'SPLIT DO UPDATE', null 
    
