    END

    /*  ## demand split info*/
    INSERT INTO dbo.TH_EXP_DEMANDSPLIT
              (
                MASTER_ID
              , PLAN_ID
              , DEMAND_ID
              , ORG_DEMAND_ID
              , DEMAND_QTY
              , ORG_DEMAND_QTY
              , PLAN_QTY
              , SHORT_QTY
              , CHECK_DEMAND
              , DEMAND_SEQ
              , CUM_ALL_QTY
              , CUM_PLAN_QTY
              , CUM_SHORT_QTY
              )
    SELECT a.MASTER_ID
         , a.PLAN_ID
         , isnull(b.DEMAND_ID, a.NET_DEMAND_ID) AS demand_id
         , a.NET_DEMAND_ID AS org_demand_id
         , CASE WHEN b.org_demand_id IS NULL THEN a.QTY
                ELSE (isnull(b.plan_qty, 0) + isnull(b.short_qty, 0))
           END  AS demand_qty
         , a.QTY AS org_demand_qty
         , isnull(b.plan_qty, 0) AS plan_qty
         , isnull(b.short_qty, 0) AS short_qty
         , CASE WHEN b.org_demand_id IS NULL THEN 'X'
                ELSE NULL
           END  AS check_demand
         , rank() OVER(PARTITION BY a.NET_DEMAND_ID
                       ORDER     BY isnull(b.DEMAND_ID, a.NET_DEMAND_ID))/* @@@ dense_rank @@@*/ AS demand_seq
         , sum(isnull(b.plan_qty, 0) + isnull(b.short_qty, 0)) OVER(PARTITION BY a.NET_DEMAND_ID) AS cum_all_qty
         , sum(isnull(b.plan_qty, 0)) OVER(PARTITION BY a.NET_DEMAND_ID) AS cum_plan_qty
         , sum(isnull(b.short_qty, 0)) OVER(PARTITION BY a.NET_DEMAND_ID) AS cum_short_qty
    FROM   dbo.TH_DPP_NET_DEMAND  AS a 
              LEFT OUTER JOIN 
              (
                SELECT a.org_demand_id AS org_demand_id
                     , a.DEMAND_ID
                     , floor(sum(a.plan_qty)) AS plan_qty
                     , ceiling(sum(a.short_qty)) AS short_qty
                FROM   (
                        SELECT CASE WHEN CHARINDEX('##',a.DEMAND_ID) = 0 THEN a.DEMAND_ID
                                    ELSE substring(a.DEMAND_ID, 1, CHARINDEX('##', a.DEMAND_ID) - 1)
                               END  AS org_demand_id
                             , a.DEMAND_ID
                             , a.EVENT_QTY AS plan_qty
                             , 0 AS short_qty
                        FROM   dbo.TH_BUF_OUT_ITEM_PEGGING  AS a
                        WHERE  a.MASTER_ID = @v_master_id 
                        AND    a.PLAN_ID = @v_plan_id 
                        AND    a.OUT_VERSION_ID = @v_out_version_id 
                        AND    a.DEMAND_ID IS NOT NULL
                        UNION ALL
                        SELECT CASE WHEN CHARINDEX('##', a.DEMAND_ID) = 0 THEN a.DEMAND_ID
                                    ELSE substring(a.DEMAND_ID, 1, CHARINDEX('##', a.DEMAND_ID) - 1)
                               END  AS org_demand_id
                             , a.DEMAND_ID
                             , 0 AS plan_qty
                             , a.PROBLEM_QTY AS short_qty
                        FROM   dbo.TH_BUF_OUT_PROBLEM_REPORT  AS a
                        WHERE  a.MASTER_ID = @v_master_id 
                        AND    a.PLAN_ID = @v_plan_id 
                        AND    a.OUT_VERSION_ID = @v_out_version_id 
                        AND    upper(a.PROBLEM_TYPE) = 'UNPLAN'
                       )  AS a
                GROUP  BY a.org_demand_id, a.DEMAND_ID
               )  AS b 
               ON a.NET_DEMAND_ID = b.org_demand_id
    WHERE  a.MASTER_ID = @v_master_id 
    AND    a.PLAN_ID = @v_plan_id
    ORDER  BY org_demand_id, demand_id

    --LOG 생성
    EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_DEMANDSPLIT', 'INSERT', @@ROWCOUNT, null, null, null

    /* th_dpp_net_demand split*/
