    END

    /*  ## th_dpp_net_demand split insert*/
    INSERT INTO dbo.TH_DPP_NET_DEMAND
              (
                MASTER_ID
              , PLAN_ID
              , NET_DEMAND_ID
              , DEMAND_ID
              , SALES_ORDER_ID
              , SALES_MODEL
              , PRODUCTION_ORDER_ID
              , PO_TYPE
              , ITEM_ID
              , QTY
              , ORG_QTY
              , DUE_DATE
              , SHIPPING_DATE
              , DUE_FENCE_DATE
              , MFG_WEEK
              , SOP_WEEK
              , SPLIT_DATE
              , ORDER_TYPE
              , DEMAND_TYPE
              , PRODUCING_TYPE
              , FROM_SITE_ID
              , TO_SITE_ID
              , CUSTOMER_ID
              , DEMAND_GROUP_PRIORITY
              , DEMAND_PRIORITY
              , EARLY_PRODUCING_TERM
              , EARLY_PRODUCING_TERM_UOM
              , ATTRIBUTE_CHECKER_ID
              , SPLIT_QTY
              , IS_SCHEDULE
              , DESCR
              , KEY_DATE
              , INSERT_ID
              , INSERT_DTTM
              , UPDATE_ID
              , UPDATE_DTTM
              )
    SELECT a.MASTER_ID
         , @v_plan_id AS plan_id
         , b.DEMAND_ID AS net_demand_id
         , a.DEMAND_ID
         , a.SALES_ORDER_ID
         , a.SALES_MODEL
         , a.PRODUCTION_ORDER_ID
         , a.PO_TYPE
         , a.ITEM_ID
         , b.DEMAND_QTY AS qty
         , a.ORG_QTY
         , a.DUE_DATE
         , a.SHIPPING_DATE
         , a.DUE_FENCE_DATE
         , a.MFG_WEEK
         , a.SOP_WEEK
         , a.SPLIT_DATE
         , a.ORDER_TYPE
         , a.DEMAND_TYPE
         , a.PRODUCING_TYPE
         , a.FROM_SITE_ID
         , a.TO_SITE_ID
         , a.CUSTOMER_ID
         , a.DEMAND_GROUP_PRIORITY
         , a.DEMAND_PRIORITY
         , a.EARLY_PRODUCING_TERM
         , a.EARLY_PRODUCING_TERM_UOM
         , a.ATTRIBUTE_CHECKER_ID
         , a.SPLIT_QTY
         , a.IS_SCHEDULE
         , a.DESCR
         , a.KEY_DATE
         , @v_proc_name AS insert_id
         , sysdatetime() AS insert_dttm
         , @v_proc_name AS update_id
         , sysdatetime() AS update_dttm
    FROM   dbo.TH_DPP_NET_DEMAND    AS a, 
           dbo.TH_EXP_DEMANDSPLIT   AS b
    WHERE  a.MASTER_ID = b.MASTER_ID 
    AND    a.NET_DEMAND_ID = b.ORG_DEMAND_ID 
    AND    a.MASTER_ID = @v_master_id 
    AND    a.PLAN_ID = RTRIM(LTRIM(ISNULL(@v_plan_id, '') + 'BAK')) 
    AND    b.PLAN_ID = @v_plan_id

    --LOG 생성
    EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_DPP_NET_DEMAND', 'INSERT', @@ROWCOUNT, null, null, null
    */

