    --------------------------------------------------------------------------------------------------------------------------------
    -- 2017.06.19 : ORDER_ID, MIN(DEMAND_ID) 로 했으나 DEMAND_ID 에 ITEM_ID 가 첫번째라 한참 뒤의 DEMAND 와 PEGGING 되는 현상 발생
    --              그래서 DEMAND_GROUP_PRIORITY 와 DEMAND_PRIORITY 로 순서를 잡아서 처리하도록 로직 보완
    DELETE FROM TH_BUF_SCM_PLANORDER_DEMAND
    
    EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_BUF_SCM_PLANORDER_DEMAND', 'DELETE', @@ROWCOUNT, null, null, null

    INSERT INTO TH_BUF_SCM_PLANORDER_DEMAND
         (
           MASTER_ID
         , PLAN_ID
         , ORDER_ID
         , ORDER_ID_TYPE
         , DEMAND_ID
         )
    SELECT A.MASTER_ID
         , A.PLAN_ID
         , A.ORDER_ID
         , A.ORDER_ID_TYPE
         , A.DEMAND_ID
    FROM   (
            SELECT A.MASTER_ID
                 , A.PLAN_ID
                 , A.ORDER_ID
                 , A.ORDER_ID_TYPE
                 , A.DEMAND_ID
                 , DENSE_RANK() OVER (PARTITION BY A.ORDER_ID 
                                      ORDER     BY A.PRIORITY_GROUP
                                                 , A.PRIORITY
                                                 , A.DEMAND_ID) AS SEQ
            FROM   (
                    SELECT A.MASTER_ID
                         , A.PLAN_ID
                         , A.ORDER_ID
                         , A.ORDER_ID_TYPE
                         , A.DEMAND_ID
                         , ISNULL(B.DEMAND_GROUP_PRIORITY,  'ZZZZ') AS PRIORITY_GROUP
                         , ISNULL(B.DEMAND_PRIORITY,        'ZZZZ') AS PRIORITY
                    FROM   (
                            SELECT A.MASTER_ID
                                 , A.PLAN_ID
                                 , A.ORDER_ID
                                 , A.ORDER_ID_TYPE
                                 , A.DEMAND_ID
                            FROM   DBO.TH_BUF_OUT_ORDER_TRACKING  AS A
                            WHERE  A.MASTER_ID      = @v_master_id
                            AND    A.PLAN_ID        = @v_plan_id
                            AND    A.OUT_VERSION_ID = @v_out_version_id
                            AND    ISNULL(A.ORDER_ID_TYPE, '-') <> '-'
                            AND    ISNULL(A.DEMAND_ID, '-')     <> '-'
                            GROUP  BY 
                                   A.MASTER_ID
                                 , A.PLAN_ID
                                 , A.ORDER_ID
                                 , A.ORDER_ID_TYPE
                                 , A.DEMAND_ID
                           ) A
                           LEFT OUTER JOIN TH_DPP_NET_DEMAND AS B
                                ON     A.MASTER_ID  = B.MASTER_ID
                                AND    A.PLAN_ID    = B.PLAN_ID
                                AND    A.DEMAND_ID  = B.NET_DEMAND_ID
                   ) A
           ) A
    WHERE   SEQ = 1
    
    EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_BUF_SCM_PLANORDER_DEMAND', 'INSERT', @@ROWCOUNT, null, null, null

