    DELETE FROM TH_BUF_SCM_PLANORDER_WORK
    
    EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_BUF_SCM_PLANORDER_WORK', 'DELETE', @@ROWCOUNT, null, null, null

    INSERT INTO TH_BUF_SCM_PLANORDER_WORK
    SELECT DISTINCT
            a.MASTER_ID
          , a.PLAN_ID
          , a.WORK_ORDER_ID
          , CONVERT(nvarchar(max), b.PLAN_START_DTTM, 112) AS plan_start_date
          , CASE CHARINDEX('^', a.ITEM_ID) WHEN 0 THEN a.ITEM_ID
                                           ELSE substring(a.ITEM_ID, 1, CHARINDEX('^', a.ITEM_ID) - 1)
            END AS item_id
          , CASE CHARINDEX('^', a.ROUTE_ID) WHEN 0 THEN a.ROUTE_ID
                                           ELSE substring(a.ROUTE_ID, 1, CHARINDEX('^', a.ROUTE_ID) - 1)
            END AS route_id
          , a.operation_id
     FROM   dbo.TH_BUF_OUT_WORK_ORDER   AS a, 
            dbo.TH_ENG_PLAN_INFO    AS b
     WHERE  a.MASTER_ID = b.MASTER_ID 
     AND    a.PLAN_ID = b.PLAN_ID 
     AND    a.MASTER_ID = @v_master_id 
     AND    a.PLAN_ID = @v_plan_id 
     AND    a.OUT_VERSION_ID = @v_out_version_id 
     AND    a.RESOURCE_ID IN (
                              SELECT a.RESOURCE_ID
                              FROM   dbo.TH_ENG_RESOURCE  AS a
                              WHERE  a.MASTER_ID = @v_master_id 
                              AND    a.PLAN_ID = @v_plan_id 
                              AND    a.RESOURCE_TYPE = 'MAIN'
                             )
     GROUP BY a.MASTER_ID
            , a.PLAN_ID
            , a.WORK_ORDER_ID
            , CONVERT(nvarchar(max), b.PLAN_START_DTTM, 112)
            , CASE CHARINDEX('^', a.ITEM_ID) WHEN 0 THEN a.ITEM_ID
                                                    ELSE substring(a.ITEM_ID, 1, CHARINDEX('^', a.ITEM_ID) - 1)
              END
            , CASE CHARINDEX('^', a.ROUTE_ID) WHEN 0 THEN a.ROUTE_ID
                                                     ELSE substring(a.ROUTE_ID, 1, CHARINDEX('^', A.ROUTE_ID) - 1)
              END
            , a.operation_id   
                  
                    
    EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_BUF_SCM_PLANORDER_WORK', 'INSERT', @@ROWCOUNT, null, null, null

                    
    INSERT INTO TH_BUF_SCM_PLANORDER
     SELECT 
           DISTINCT
            a.MASTER_ID
          , a.PLAN_ID
          , a.WORK_ORDER_ID as order_id
          , a.plan_start_date
          , isnull(b.demand_id, c.demand_id) AS demand_id
          , isnull(b.org_demand_id, c.org_demand_id) AS org_demand_id
          , isnull(b.production_type, c.production_type) AS production_type
          , a.item_id
          , a.route_id
          , a.operation_id
          , isnull(d.erp_operation_id, 'ZZ') as erp_operation_id
          , ISNULL(d.order_type, 'V') AS order_type
          , ISNULL(d.order_type, 'V') 
                         + @v_instance_code
                         + isnull(isnull(b.production_type, c.production_type), 'X')
                         + @v_order_date_code
                         + isnull(d.erp_operation_id, 'ZZ')
              as order_head
     FROM   TH_BUF_SCM_PLANORDER_WORK AS a
                LEFT OUTER JOIN (
                  SELECT a.WORK_ORDER_ID
                       , a.demand_id AS demand_id
                       , b.org_demand_id AS org_demand_id
                       , b.production_type AS production_type
                  FROM   (
                          SELECT a.WORK_ORDER_ID
                               , min(a.DEMAND_ID) AS demand_id
                          FROM   dbo.TH_ENG_FIXED_PLAN  AS a
                          WHERE  a.MASTER_ID = @v_master_id 
                          AND    a.PLAN_ID = @v_plan_id 
                          AND    isnull(RTRIM(LTRIM(a.DEMAND_ID)), '-') <> '-'
                          GROUP BY a.WORK_ORDER_ID
                         )  AS a, 
                         (
                          SELECT a.NET_DEMAND_ID
                               , a.DEMAND_ID AS org_demand_id
                               , ISNULL(B.KEY_VALUE, 'X') AS production_type
                          FROM   dbo.TH_DPP_NET_DEMAND  AS a
                                 LEFT OUTER JOIN SY_FP_INSTANCE_CONFIG_M  AS B
                                  ON  B.INSTANCE_ID = 'COMMON'
                                  AND B.CATEGORY_ID = 'DEMAND_TYPE'
                                  AND B.KEY_ID = A.ORDER_TYPE
                          WHERE  a.MASTER_ID = @v_master_id 
                          AND    a.PLAN_ID = @v_plan_id
                         )  AS b
                  WHERE  a.demand_id = b.NET_DEMAND_ID
                  )  AS b 
                  ON a.work_order_id = b.WORK_ORDER_ID 
                LEFT OUTER JOIN (
                  SELECT a.ORDER_ID
                       , a.demand_id AS demand_id
                       , b.org_demand_id AS org_demand_id
                       , b.production_type AS production_type
                  FROM   (
                          -- DEMAND 채번 규칙 변경
                          SELECT a.ORDER_ID
                               , min(a.DEMAND_ID) AS demand_id
                          FROM   TH_BUF_SCM_PLANORDER_DEMAND A
                          WHERE  a.MASTER_ID = @v_master_id 
                          AND    a.PLAN_ID = @v_plan_id 
                          AND    a.ORDER_ID_TYPE = 'W' 
                          GROUP  BY a.ORDER_ID
                          /*
                          SELECT a.ORDER_ID
                               , min(a.DEMAND_ID) AS demand_id
                          FROM   dbo.TH_BUF_OUT_ORDER_TRACKING  AS a
                          WHERE  a.MASTER_ID = @v_master_id 
                          AND    a.PLAN_ID = @v_plan_id 
                          AND    a.OUT_VERSION_ID = @v_out_version_id 
                          AND    a.ORDER_ID_TYPE = 'W' 
                          AND    isnull(a.DEMAND_ID, '-') <> '-'
                          GROUP BY a.ORDER_ID
                          */
                         )  AS a, 
                         (
                          SELECT a.NET_DEMAND_ID
                               , a.DEMAND_ID AS org_demand_id
                               , ISNULL(B.KEY_VALUE, 'X') AS production_type
                          FROM   dbo.TH_DPP_NET_DEMAND  AS a
                                 LEFT OUTER JOIN SY_FP_INSTANCE_CONFIG_M  AS B
                                  ON  B.INSTANCE_ID = 'COMMON'
                                  AND B.CATEGORY_ID = 'DEMAND_TYPE'
                                  AND B.KEY_ID = A.ORDER_TYPE
                          WHERE  a.MASTER_ID = @v_master_id 
                          AND    a.PLAN_ID = @v_plan_id
                         )  AS b
                  WHERE a.demand_id = b.NET_DEMAND_ID
                  )  AS c 
                  ON a.work_order_id = c.ORDER_ID
                LEFT OUTER JOIN (
                  SELECT DISTINCT
                         ITEM_ID, OPERATION_ID, ERP_OPERATION_ID, ORDER_TYPE
                  FROM   DBO.TH_MST_INSTANCE_FLOW
                  WHERE  MASTER_ID = @V_MASTER_ID
                  AND    PLAN_ID   = @V_PLAN_ID
                  )  AS D
                  ON  A.ITEM_ID = D.ITEM_ID
                  AND A.OPERATION_ID = D.OPERATION_ID                                                                                                               

    EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_BUF_SCM_PLANORDER - WO', 'INSERT', @@ROWCOUNT, null, null, null

    DELETE FROM TH_BUF_SCM_PLANORDER_DELIVERY
    
    EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_BUF_SCM_PLANORDER_DELIVERY', 'DELETE', @@ROWCOUNT, null, null, null

    INSERT INTO TH_BUF_SCM_PLANORDER_DELIVERY
    SELECT DISTINCT
            a.MASTER_ID
          , a.PLAN_ID
          , a.DELIVERY_ORDER_ID
          , CONVERT(nvarchar(max), b.PLAN_START_DTTM, 112) AS plan_start_date
          , CASE CHARINDEX('^', a.ITEM_ID) WHEN 0 THEN a.ITEM_ID
                                                  ELSE substring(a.ITEM_ID, 1, CHARINDEX('^', a.ITEM_ID) - 1)
            END AS item_id
            -- 이동 지시 계획의 경우 출발지 기준으로 함.
          , CASE CHARINDEX('^', a.FROM_ROUTE_ID) WHEN 0 THEN a.FROM_ROUTE_ID
                                           ELSE substring(a.FROM_ROUTE_ID, 1, CHARINDEX('^', a.FROM_ROUTE_ID) - 1)
            END AS route_id
          , a.from_operation_id as operation_id
          , CASE WHEN CHARINDEX('::', a.DELIVERY_ORDER_ID) = 0 THEN a.DELIVERY_ORDER_ID
                 ELSE SUBSTRING(a.DELIVERY_ORDER_ID, 1, CHARINDEX('::', a.DELIVERY_ORDER_ID)-1)
            END  ORG_DELIVERY_ORDER_ID
     FROM   dbo.TH_BUF_OUT_DELIVERY_ORDER   AS a, 
            dbo.TH_ENG_PLAN_INFO        AS b
     WHERE  a.MASTER_ID = b.MASTER_ID 
     AND    a.PLAN_ID = b.PLAN_ID 
     AND    a.MASTER_ID = @v_master_id 
     AND    a.PLAN_ID = @v_plan_id 
     AND    a.OUT_VERSION_ID = @v_out_version_id
     GROUP  BY a.MASTER_ID
             , a.PLAN_ID
             , a.DELIVERY_ORDER_ID
             , CONVERT(nvarchar(max), b.PLAN_START_DTTM, 112)
             , CASE CHARINDEX('^', a.ITEM_ID) WHEN 0 THEN a.ITEM_ID
                                                     ELSE substring(a.ITEM_ID, 1, CHARINDEX('^', a.ITEM_ID) - 1)
               END
             , CASE CHARINDEX('^', a.FROM_ROUTE_ID) WHEN 0 THEN a.FROM_ROUTE_ID
                                              ELSE substring(a.FROM_ROUTE_ID, 1, CHARINDEX('^', a.FROM_ROUTE_ID) - 1)
               END
             , CASE WHEN CHARINDEX('::', a.DELIVERY_ORDER_ID) = 0 THEN a.DELIVERY_ORDER_ID
                    ELSE SUBSTRING(a.DELIVERY_ORDER_ID, 1, CHARINDEX('::', a.DELIVERY_ORDER_ID)-1)
               END  
             , a.from_operation_id

    EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_BUF_SCM_PLANORDER_DELIVERY', 'INSERT', @@ROWCOUNT, null, null, null
             
    INSERT INTO TH_BUF_SCM_PLANORDER
     SELECT DISTINCT
            a.MASTER_ID
          , a.PLAN_ID
          , a.DELIVERY_ORDER_ID as order_id
          , a.plan_start_date
          , b.demand_id
          , b.org_demand_id
          , b.production_type
          , a.item_id
          , a.route_id
          , a.operation_id
          , d.erp_operation_id
          , @v_to_head as order_type
          , @v_to_head   
                         + @v_instance_code
                         + isnull(b.production_type, 'X')
                         + @v_order_date_code
                         + isnull(d.erp_operation_id, 'ZZ')
              as order_head
     FROM   TH_BUF_SCM_PLANORDER_DELIVERY  AS a
                LEFT OUTER JOIN (
                  SELECT a.ORDER_ID
                       , a.demand_id AS demand_id
                       , b.org_demand_id AS org_demand_id
                       , b.production_type AS production_type
                  FROM   (
                          -- DEMAND 채번 규칙 변경
                          SELECT a.ORDER_ID
                               , min(a.DEMAND_ID) AS demand_id
                          FROM   TH_BUF_SCM_PLANORDER_DEMAND A
                          WHERE  a.MASTER_ID = @v_master_id 
                          AND    a.PLAN_ID = @v_plan_id 
                          AND    a.ORDER_ID_TYPE = 'D' 
                          GROUP  BY a.ORDER_ID
                          /*
                          SELECT a.ORDER_ID
                               , min(a.DEMAND_ID) AS demand_id
                          FROM   dbo.TH_BUF_OUT_ORDER_TRACKING  AS a
                          WHERE  a.MASTER_ID = @v_master_id 
                          AND    a.PLAN_ID = @v_plan_id 
                          AND    a.OUT_VERSION_ID = @v_out_version_id 
                          AND    a.ORDER_ID_TYPE = 'D' 
                          AND    isnull(a.DEMAND_ID, '-') <> '-'
                          GROUP BY a.ORDER_ID
                          */
                         )  AS a, 
                         (
                          SELECT a.NET_DEMAND_ID
                               , a.DEMAND_ID AS org_demand_id
                               , ISNULL(B.VALUE, 'X') AS production_type
                          FROM   dbo.TH_DPP_NET_DEMAND  AS a
                                 LEFT OUTER JOIN dbo.TH_CFG_CONFIG_VALUE  AS B
                                  ON  B.PLAN_TYPE = 'DEMAND'
                                  AND B.CONFIG_SET_ID = 'PRODUCTION_TYPE'
                                  AND B.KEY_ID = A.ORDER_TYPE
                          WHERE  a.MASTER_ID = @v_master_id 
                          AND    a.PLAN_ID = @v_plan_id
                         )  AS b
                  WHERE  a.demand_id = b.NET_DEMAND_ID
                  )  AS b 
                  ON a.ORG_DELIVERY_ORDER_ID = b.ORDER_ID
                INNER JOIN (
                  SELECT DISTINCT
                         ITEM_ID, OPERATION_ID, ERP_OPERATION_ID, ORDER_TYPE
                  FROM   DBO.TH_MST_INSTANCE_FLOW
                  WHERE  MASTER_ID = @V_MASTER_ID
                  AND    PLAN_ID   = @V_PLAN_ID
                  )  AS D
                  ON  A.ITEM_ID = D.ITEM_ID
                  AND A.OPERATION_ID = D.OPERATION_ID                                                        

    EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_BUF_SCM_PLANORDER - TO', 'INSERT', @@ROWCOUNT, null, null, null

    DECLARE @n_order_seq int = 0
/*    
    SELECT @n_order_seq = CASE WHEN MAX(ORDER_NO) IS NULL THEN 0 ELSE MAX(ORDER_NO) END
    FROM   SY_FP_ORDER_SEQ A,
           (
            SELECT MAX(SUBSTRING(WORK_ORDER_ID, ORDER_HEAD_LENGTH, 3)) WORK_ORDER_TAIL
            FROM   TH_BUF_OUT_WORK_ORDER A,
                   (
                    SELECT OPERATION_ID, ORDER_HEAD, LEN(ORDER_HEAD) ORDER_HEAD_LENGTH
                    FROM   TH_BUF_SCM_PLANORDER
                    GROUP  BY OPERATION_ID, ORDER_HEAD
                   ) B
            WHERE  A.MASTER_ID = @v_master_id
            AND    A.PLAN_ID = @v_plan_id
            AND    A.OUT_VERSION_ID = @v_out_version_id
            AND    A.WORK_ORDER_ID LIKE B.ORDER_HEAD + '%'
           ) B
    WHERE  A.ORDER_ID = B.WORK_ORDER_TAIL
*/    
    EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, '@n_order_seq', 'SELECT', @n_order_seq, null, null, null


    /*  ## plan order info*/
    INSERT INTO dbo.TH_EXP_PLANORDER
              (
                MASTER_ID
              , PLAN_ID
              , ORDER_ID
              , PLAN_ORDER_ID
              , ORDER_TYPE
              , PLAN_START_DATE
              , DEMAND_ID
              , ORG_DEMAND_ID
              , ITEM_ID
              )
    SELECT DISTINCT
           fci.MASTER_ID
         , fci.PLAN_ID
         , fci.order_id
         , fci.plan_order_id
         , fci.order_type
         , fci.plan_start_date
         , fci.demand_id
         , fci.org_demand_id
         , fci.item_id
    FROM  (
           SELECT fci.MASTER_ID
                , fci.PLAN_ID
                , fci.order_id AS order_id
                , fci.plan_order_id AS plan_order_id
                , fci.order_type AS order_type
                , fci.plan_start_date AS plan_start_date
                , isnull(fci.demand_id, fci.plan_order_id) AS demand_id
                , isnull(fci.org_demand_id, fci.plan_order_id) AS org_demand_id
                , fci.item_id AS item_id
                , rank() OVER(PARTITION BY fci.MASTER_ID, fci.PLAN_ID, fci.plan_order_id
                              ORDER     BY (CASE WHEN order_id = plan_order_id THEN 1
                                                 ELSE 2
                                            END), order_id) AS r
           FROM   (
                   SELECT a.MASTER_ID
                        , a.PLAN_ID
                        , a.order_id AS order_id
                        , CASE WHEN b.WORK_ORDER_ID IS NOT NULL  THEN a.order_id        -- FIXED PLAN 에 존재하는 경우는 이것을
                               WHEN Z.FIX_ORDER_ID  IS NOT NULL  THEN Z.FIX_ORDER_ID    -- FIX WORK 으로 CHANGE 하는 애들은 이것을
                               ELSE isnull(c.WORK_ORDER_ID, a.order_head + x.order_id)
                          END  AS plan_order_id
                        , a.order_type AS order_type
                        , a.plan_start_date AS plan_start_date
                        , a.demand_id AS demand_id
                        , a.org_demand_id AS org_demand_id
                        , a.item_id AS item_id
                   FROM   (
                            select a.*,
                                   @n_order_seq + ( row_number() over ( partition by order_head order by order_id, DEMAND_ID, ITEM_ID, ROUTE_ID, OPERATION_ID)) ord_seq
                            from   TH_BUF_SCM_PLANORDER a
                          )  AS a 
                          LEFT OUTER JOIN (
                                            SELECT DISTINCT A.WORK_ORDER_ID
                                            FROM   TH_MST_FIXED_PLAN  AS A
                                            WHERE  A.MASTER_ID = @v_master_id 
                                            AND    A.PLAN_ID = @v_plan_id 
                                            AND    A.PO_TYPE IN ( 'FIX', 'ACO','REPLAN' )
                                           )  AS b 
                               ON a.order_id = b.WORK_ORDER_ID 
                          LEFT OUTER JOIN (
                                            SELECT fci.DEMAND_ID
                                                 , fci.ROUTE_ID
                                                 , fci.OPERATION_ID
                                                 , fci.ITEM_ID
                                                 , fci.order_type AS order_type
                                                 , fci.WORK_ORDER_ID
                                            FROM   (
                                                    SELECT SSMAROWNUM.DEMAND_ID
                                                         , SSMAROWNUM.ROUTE_ID
                                                         , SSMAROWNUM.OPERATION_ID    -- 추가
                                                         , SSMAROWNUM.ITEM_ID
                                                         , SSMAROWNUM.order_type
                                                         , SSMAROWNUM.WORK_ORDER_ID
                                                         , rank() OVER(PARTITION BY SSMAROWNUM.DEMAND_ID, SSMAROWNUM.ROUTE_ID, SSMAROWNUM.ITEM_ID
                                                                       ORDER     BY SSMAROWNUM.COMPLETE_QTY DESC, SSMAROWNUM.WORK_ORDER_ID, SSMAROWNUM.ROWNUM) AS r
                                                    FROM   (
                                                            SELECT DEMAND_ID
                                                                 , ROUTE_ID
                                                                 , OPERATION_ID   -- 추가
                                                                 , ITEM_ID
                                                                 , WORK_ORDER_ID
                                                                 , COMPLETE_QTY
                                                                 , MASTER_ID
                                                                 , PLAN_ID
                                                                 , PO_TYPE
                                                                 , ORDER_TYPE
                                                                 , ROW_NUMBER() OVER(ORDER BY SSMAPSEUDOCOLUMN) AS ROWNUM
                                                            FROM   (
                                                                    SELECT a.DEMAND_ID
                                                                         , a.ROUTE_ID
                                                                         , A.OPERATION_ID   -- 추가
                                                                         , a.ITEM_ID
                                                                         , a.WORK_ORDER_ID
                                                                         , a.COMPLETE_QTY
                                                                         , a.MASTER_ID
                                                                         , a.PLAN_ID
                                                                         , a.PO_TYPE
                                                                         , a.ORDER_TYPE
                                                                         , 0 AS SSMAPSEUDOCOLUMN
                                                                    FROM   dbo.TH_MST_FIXED_PLAN  AS a
                                                                    WHERE  a.MASTER_ID = @v_master_id 
                                                                    AND    a.PLAN_ID = @v_plan_id 
                                                                    AND    a.PO_TYPE IN ( 'FIX', 'ACO', 'REPLAN' ) 
                                                                    AND    a.ORDER_TYPE = 'W' 
                                                                    AND    RTRIM(LTRIM(a.DEMAND_ID)) IS NOT NULL
                                                                   )  AS SSMAPSEUDO
                                                           )  AS SSMAROWNUM
                                                    WHERE  SSMAROWNUM.MASTER_ID = @v_master_id 
                                                    AND    SSMAROWNUM.PLAN_ID = @v_plan_id 
                                                    AND    SSMAROWNUM.PO_TYPE IN ( 'FIX', 'ACO', 'REPLAN' ) 
                                                    AND    SSMAROWNUM.ORDER_TYPE = 'W' 
                                                    AND    RTRIM(LTRIM(SSMAROWNUM.DEMAND_ID)) IS NOT NULL
                                                   )  AS fci
                                            WHERE  fci.r = 1
                                          )  AS c 
                               ON  a.demand_id = c.DEMAND_ID 
                               AND a.route_id = c.ROUTE_ID 
                               and a.operation_id = c.operation_id
                               AND a.item_id = c.ITEM_ID 
                               AND a.order_type = c.order_type
                          LEFT OUTER JOIN 
                                          (select DISTINCT
                                                  item_id, operation_id, erp_operation_id
                                           from   dbo.TH_MST_INSTANCE_FLOW
                                           where  master_id = @v_master_id
                                           and    plan_id   = @v_plan_id
                                          ) as y                              
                               ON  a.item_id = y.item_id
                               and    a.operation_id = y.operation_id
                          LEFT OUTER JOIN TH_EXP_FIXORDER Z
                               on    a.master_id = z.master_id
                               and   a.plan_id   = z.plan_id
                               and   a.order_id  = z.order_id + 'XXXX'
                         ,SY_FP_ORDER_SEQ as x
                    where  a.ord_seq = x.ORDER_NO
                  )  AS fci
           )  AS fci
    WHERE  fci.r = 1

    --LOG 생성
    EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_PLANORDER', 'INSERT', @@ROWCOUNT, null, null, null

/*
    UPDATE TH_EXP_PLANORDER
    SET    TH_EXP_PLANORDER.PLAN_ORDER_ID = C.WORK_ORDER_ID
    FROM   TH_EXP_PLANORDER A,
           TH_BUF_SCM_PLANORDER B,
           TH_MST_FIXED_PLAN C
    WHERE  A.MASTER_ID    = B.MASTER_ID
    AND    A.PLAN_ID      = B.PLAN_ID
    AND    A.ORDER_ID     = B.ORDER_ID
    AND    A.DEMAND_ID    = B.DEMAND_ID
    AND    A.MASTER_ID    = C.MASTER_ID
    AND    A.PLAN_ID      = C.PLAN_ID
    AND    A.DEMAND_ID    = C.DEMAND_ID
    AND    A.ITEM_ID      = C.ITEM_ID
    AND    B.OPERATION_ID = C.OPERATION_ID
    AND    A.MASTER_ID    = @v_master_id
    AND    A.PLAN_ID      = @v_plan_id
*/    
    --LOG 생성
    EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, null, 'END', null, null, '=============== End of procedure ===============', null

  END TRY

  BEGIN CATCH
    BEGIN

      DECLARE 
         @v_error_message nvarchar(max),
         @v_error_procedure nvarchar(max),
         @v_error_line nvarchar(max)

      SET @v_error_message = ERROR_MESSAGE()

      SET @v_error_procedure = ERROR_PROCEDURE()

      SET @v_error_line = convert(nvarchar,ERROR_LINE())


      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_error_procedure, null, 'ERROR', null, @v_error_line, null, @v_error_message

      IF @@TRANCOUNT > 0
         COMMIT WORK 
    END
  END CATCH
END
